mapper.select:
select id , api_code , file_type as fileType , file_name as fileName , task_number as taskNumber , start_date as startDate , status , file_child_dir as fileChildDir , DATE_FORMAT(create_time,'%Y-%m-%d %H:%i:%s') as createTime , DATE_FORMAT(update_time,'%Y-%m-%d %H:%i:%s') as updateTime from b_transfer_file_task btft
and create_time >=#{startDateStart}
and create_time <#{startDateEnd}
and (api_code like concat("%", #{serach},"%") or file_name like concat("%", #{serach},"%"))
order by create_time desc,id desc

mapper.delete:
delete from b_extra_file_task_action
where task_id = #{mrpExtraTaskId}
    and action_date = #{actionDate}
